<?php
if(!defined('ABSPATH')) { exit; }
final class HPG_Pages {
    public static function navigation() {
        ?><nav class="hpg-nav" aria-label="GitHub Sync pages"><?php foreach(['hpg-sync'=>'Push','hpg-git'=>'Git Review & Merge','hpg-settings'=>'Settings','hpg-profiles'=>'Profiles','hpg-history'=>'History'] as $page=>$label): if(!HPG_Access::admin() && !in_array($page,['hpg-sync','hpg-git'],true)) { continue; } ?><a class="<?php echo ($_GET['page']??'')===$page?'selected':''; ?>" href="<?php echo esc_url(admin_url('admin.php?page='.$page)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav><?php
    }
    public static function context() {
        $profiles=get_posts(['post_type'=>HPG_Sync::TYPE,'post_status'=>'private','numberposts'=>-1]);$id=absint($_GET['profile']??0);if(!$id && $profiles) { $id=$profiles[0]->ID; }if($id && get_post_type($id)!==HPG_Sync::TYPE) { $id=0; }return [$profiles,$id];
    }
    public static function head($title,$page,$profiles,$id) {
        ?><div class="wrap hpg"><div class="hpg-head"><div><span class="hpg-kicker">HARSH PATEL / DEVELOPER TOOLS</span><h1><?php echo esc_html($title); ?>.</h1><p><?php echo $page==='hpg-sync'?'Preview and push a saved profile.':'Compare two branches, review a request, and merge on GitHub.'; ?></p></div><div class="hpg-head-links"><?php if(HPG_Access::admin()): ?><a class="hpg-btn" href="<?php echo esc_url(admin_url('admin.php?page=hpg-profiles&profile=0')); ?>">+ New profile</a><?php endif; ?><span class="hpg-badge">v1.0</span></div></div><?php self::navigation(); ?><form method="get"><input type="hidden" name="page" value="<?php echo esc_attr($page); ?>"><label>Select profile</label><select name="profile" onchange="this.form.submit()"><?php foreach($profiles as $profile): ?><option value="<?php echo esc_attr($profile->ID); ?>" <?php selected($id,$profile->ID); ?>><?php echo esc_html($profile->post_title); ?></option><?php endforeach; ?></select></form><?php
    }
    public static function result($id) {
        $r=HPG_Sync::consume_notice($id);if(is_array($r)): $level=$r['level']??($r['ok']?'success':'error'); ?><div class="hpg-alert <?php echo esc_attr($level); ?>"><strong><?php echo esc_html(($level==='warning'?'Review needed':($r['ok']?'Completed':'Action failed')).' · '.$r['action']); ?></strong><pre><?php echo esc_html($r['message']); ?></pre></div><?php endif;
        $p=HPG_Sync::process_data($id);?><section class="hpg-card hpg-process" data-state="<?php echo esc_attr($p['state']??'ready'); ?>"><strong>Process status</strong><p id="hpg-process-text" role="status"><?php echo esc_html(is_array($p)?$p['state'].' · '.$p['phase'].(isset($p['elapsed'])?' · '.HPG_Sync::duration($p['elapsed']).' elapsed':''):'Ready · choose an action'); ?></p></section><?php
    }
    public static function form($id,$page) {
        ?><form action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post"><input type="hidden" name="action" value="hpg_sync"><input type="hidden" name="profile" value="<?php echo esc_attr($id); ?>"><input type="hidden" name="return_page" value="<?php echo esc_attr($page); ?>"><?php wp_nonce_field('hpg_sync'); ?><?php
    }
    public static function token_eye($id) {
        if(!HPG_Access::admin() || !$id) { return; }
        ?><div class="hpg-token-eye"><button type="button" class="hpg-btn secondary" data-hpg-token-eye data-profile="<?php echo esc_attr($id); ?>" data-nonce="<?php echo esc_attr(wp_create_nonce('hpg_reveal_token')); ?>" aria-pressed="false">◉ Show saved token</button><input type="password" class="hpg-stored-token-view" readonly hidden autocomplete="off" aria-label="Saved GitHub token"><p class="hpg-help hpg-token-message" role="status">Click the eye button to check the stored token. This view is separate from the field for entering a new token.</p></div><?php
    }
    public static function files($id,$c) {
        $large_files=get_post_meta($id,'_hpg_large_files',true);$large_scanned=get_post_meta($id,'_hpg_large_time',true);
        ?><span class="hpg-kicker">02 / SELECT CODE</span><h2>Files to upload</h2><label for="hpg-paths">Source paths · one per line, relative to the WordPress root</label><textarea id="hpg-paths" name="paths" rows="4" required><?php echo esc_textarea($c['paths']); ?></textarea><?php self::path_picker($id,'hpg-paths','Choose files / folders to upload'); ?>
        <div class="hpg-scope-box"><label class="hpg-check"><input type="checkbox" name="include_all" value="1" <?php checked(!empty($c['include_all'])); ?>> Include configuration, uploads, backups, and credential files</label><p class="hpg-sensitive">wp-config.php contains credentials and security salts. Use a private repository before uploading it.</p></div>
        <label for="hpg-excludes">Files or folders to exclude · optional, one path or glob per line</label><textarea id="hpg-excludes" name="excludes" rows="4"><?php echo esc_textarea($c['excludes']); ?></textarea><?php self::path_picker($id,'hpg-excludes','Choose files / folders to exclude'); ?>
        <section class="hpg-large-box"><span class="hpg-kicker">LARGE FILE REVIEW</span><h3>File size and upload choice</h3><?php $size=(int)$c['size_mb'];$preset=$size===0?'unlimited':(in_array($size,[50,100],true)?(string)$size:'custom'); ?><label for="hpg-size-preset">File size option · per file</label><select id="hpg-size-preset" name="size_preset" onchange="document.getElementById('hpg-size').disabled=this.value!=='custom';document.getElementById('hpg-custom-size').hidden=this.value!=='custom';"><?php foreach(['50'=>'50 MB (50 MiB)','100'=>'100 MB (100 MiB)','custom'=>'Custom','unlimited'=>'Unlimited'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($preset,(string)$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><div id="hpg-custom-size" <?php echo $preset!=='custom'?'hidden':''; ?>><label for="hpg-size">Custom size · minimum 10 MiB</label><input id="hpg-size" name="size_mb" type="number" min="10" step="1" value="<?php echo esc_attr(max(10,$size)); ?>" <?php echo $preset!=='custom'?'disabled':''; ?>></div><p class="hpg-help">Files up to this size are included. For files above it, choose Ask, No (skip), or Yes (upload reviewed files) below. Choose No for a strict size limit. Unlimited includes all selected sizes. GitHub limits and LFS requirements still apply; the scan lists files over <?php echo esc_html(min(50,$size?:50)); ?> MiB.</p><button class="hpg-btn secondary" name="task" value="scan_large">Scan selected folders</button><p class="hpg-help">Scans only your selected source paths after exclusions. This does not upload files.</p>
        <div data-hpg-scan-results <?php echo empty($_GET['scan'])?'hidden':''; ?>><?php if($large_scanned): ?><p class="hpg-help">Last scan: <?php echo esc_html(wp_date('M j, Y · H:i:s',$large_scanned)); ?> · <?php echo esc_html(count((array)$large_files)); ?> large files.</p><?php endif; ?>
        <?php if(is_array($large_files) && $large_files): ?><div class="hpg-large-list hpg-table-wrap"><table class="hpg-table"><thead><tr><th>File path</th><th>Size</th><th>Upload method</th></tr></thead><tbody><?php foreach($large_files as $file): ?><tr><td><code><?php echo esc_html($file['path']); ?></code></td><td><?php echo esc_html(number_format($file['size']/1048576,2)); ?> MiB</td><td><?php echo $file['size']>104857600?'Git LFS required':'Regular Git'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php elseif($large_scanned): ?><p>No selected files exceed <?php echo esc_html(min(50,$size?:50)); ?> MiB.</p><?php endif; ?>
        </div><label for="hpg-large-mode">Do you want to upload these large files?</label><select id="hpg-large-mode" name="large_mode"><?php foreach(['ask'=>'Ask before upload','skip'=>'No — skip large files','upload'=>'Yes — upload reviewed large files'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($c['large_mode'],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select>
        <label class="hpg-check"><input type="checkbox" name="auto_large" value="1" <?php checked(!empty($c['auto_large'])); ?>> Automatically approve new or changed large files when Yes — upload is selected</label><p class="hpg-help">Applies to scheduled uploads too. Size exclusions and Skip still apply. Over 100 MiB requires Git LFS and available GitHub storage.</p></section>
<?php
    }
    public static function upload_sidebar($id,$c) {
        ?><aside><section class="hpg-card hpg-dark"><span class="hpg-kicker">03 / SYNC</span><h2>Upload schedule</h2><p>The selected source paths replace those same paths in the target branch. Unselected repository paths stay intact.</p><p class="hpg-help">No plugin action time limit. Server and connection limits may still apply.</p><label class="hpg-check"><input type="checkbox" name="date_branch" value="1" <?php checked(!empty($c['date_branch'])); ?>> Upload to current-date branch</label><label for="hpg-schedule">Automatic push</label><select id="hpg-schedule" name="schedule" onchange="document.getElementById('hpg-schedule-custom').hidden=this.value!=='custom';"><?php foreach(['off'=>'Manual only','hpg_15min'=>'Every 15 minutes','hourly'=>'Every hour','daily'=>'Every day','custom'=>'Custom'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($c['schedule'],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><div id="hpg-schedule-custom" <?php echo $c['schedule']!=='custom'?'hidden':''; ?>><label for="hpg-schedule-every">Push every</label><input id="hpg-schedule-every" type="number" name="schedule_every" min="1" max="1000" step="1" value="<?php echo esc_attr($c['schedule_every']); ?>"><label for="hpg-schedule-unit">Interval</label><select id="hpg-schedule-unit" name="schedule_unit"><?php foreach(['days'=>'Days','months'=>'Months','years'=>'Years'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($c['schedule_unit'],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>
        <button class="hpg-btn light" name="task" value="save_schedule">Save upload schedule</button>
        <?php if(function_exists('wp_next_scheduled')): $next=wp_next_scheduled('hpg_sync_tick',[$id]);if($next): ?><p class="hpg-help">Next automatic push: <?php echo esc_html(wp_date('M j, Y · H:i:s',$next)); ?></p><?php endif;endif; ?>
        <p class="hpg-status"><?php echo get_post_meta($id,'_hpg_armed',true)&&$c['schedule']!=='off'?'● Automatic push enabled':'○ Automatic push not active'; ?></p></section>
        <section class="hpg-card"><span class="hpg-kicker">ENVIRONMENT</span><h2>Requirements</h2><ul><li>Git accessible to PHP</li><li>PHP 7.4+ with proc_open</li><li>OpenSSL for HTTPS tokens</li><li>OpenSSH for SSH connections</li><li>Readable source code</li></ul><button class="hpg-btn secondary" name="task" value="permissions">Repair workspace permissions</button></section>
        </aside><?php
    }
    public static function path_picker($id,$target,$label) {
        $event=(int)get_post_meta($id,'_hpg_preview_event',true);$data=get_post_meta($event,'_hpg_event',true);
        if(!$event || !is_array($data) || (int)($data['profile']??0)!==(int)$id || ($data['action']??'')!=='preview' || empty($data['ok'])) { return; }
        $files=HPG_History::files($event);$paths=[];
        foreach($files as $file) { if($target==='hpg-paths' && ($file['status']??'')==='D') { continue; }$path=$file['path'];if(preg_match('/[\x00-\x1F\x7F]/',$path)) { continue; }$paths[$path]='File · '.$path;$folder=dirname($path);while($folder!=='.' && $folder!=='/' && $folder!=='') { $paths[$folder]='Folder · '.$folder;$folder=dirname($folder); } }
        ksort($paths);$count=count($paths);$paths=array_slice($paths,0,2000,true);
        ?><details class="hpg-path-picker"><summary><?php echo esc_html($label); ?></summary><p class="hpg-help">From the last successful preview. Select multiple files or folders; selections and the input stay in sync.</p><label>Find a file or folder</label><input type="search" data-hpg-picker-search="<?php echo esc_attr($target); ?>" placeholder="Type to filter"><select multiple size="8" data-hpg-path-picker="<?php echo esc_attr($target); ?>" aria-label="<?php echo esc_attr($label); ?>"><?php if($target==='hpg-paths'): ?><option value="*">Whole WordPress tree · *</option><?php endif; ?><?php foreach($paths as $path=>$label): ?><option value="<?php echo esc_attr($path); ?>"><?php echo esc_html($label); ?></option><?php endforeach; ?></select><?php if($count>2000): ?><p class="hpg-help">Showing 2,000 preview choices. Use the input or download the complete preview CSV for other paths.</p><?php endif; ?></details><?php
    }
    public static function push() {
        if(!HPG_Access::allowed('push')) { if(HPG_Access::allowed('merge')) { wp_safe_redirect(admin_url('admin.php?page=hpg-git'));exit; }return; }list($profiles,$id)=self::context();self::head('GitHub Sync','hpg-sync',$profiles,$id);if(!empty($_GET['reset_done'])) { echo '<div class="hpg-alert success">Plugin data cleared. Create a new profile to start.</div>'; }if(!$id) { echo '<section class="hpg-card"><h2>Connect your repository</h2><p>Add a profile to choose your repository and branch.</p>';if(HPG_Access::admin()) { echo '<a class="hpg-btn" href="'.esc_url(admin_url('admin.php?page=hpg-profiles&profile=0')).'">+ Create profile</a>'; }echo '</section></div>';return; }
        $c=HPG_Sync::config($id);try { HPG_Access::check('preview',$c); }catch(Throwable $e) { echo '<section class="hpg-card"><p>'.esc_html($e->getMessage()).'</p></section></div>';return; }self::result($id);HPG_History::preview((int)get_post_meta($id,'_hpg_preview_event',true),$id);
        ?><?php self::form($id,'hpg-sync'); ?><div class="hpg-grid"><main><section class="hpg-card"><h2><?php echo esc_html(get_the_title($id)); ?></h2><p>Upload branch: <strong><?php echo esc_html(!empty($c['date_branch'])?wp_date('Y-m-d'):$c['branch']); ?></strong></p><p class="hpg-help">Source: <?php echo esc_html($c['paths']); ?> · No plugin action time limit. Settings and credentials are managed by administrators.</p><?php $target=!empty($c['date_branch'])?wp_date('Y-m-d'):$c['branch'];$branches=array_unique(array_merge((array)get_post_meta($id,'_hpg_branches',true),[$c['branch'],$target])); ?><label>Branch to push</label><select name="push_branch"><?php foreach($branches as $branch): if(!HPG_Access::admin() && $branch==='main') { continue; } ?><option value="<?php echo esc_attr($branch); ?>" <?php selected($target,$branch); ?>><?php echo esc_html($branch); ?></option><?php endforeach; ?></select><?php if(HPG_Access::admin()): ?><details class="hpg-branch-create"><summary>Create a branch</summary><label for="hpg-new-branch">New branch name</label><input id="hpg-new-branch" name="new_branch" placeholder="feature/my-update"><label>Starting code</label><select name="branch_mode" onchange="document.getElementById('hpg-copy-repo').hidden=this.value!=='repository';"><option value="current">Copy selected branch</option><option value="empty" selected>Empty branch · no files</option><option value="repository">Copy another repository</option></select><div id="hpg-copy-repo" hidden><label>Source repository URL</label><input name="branch_source_url" placeholder="https://github.com/owner/repo.git"><label>Source branch</label><input name="branch_source_name" value="main"><p class="hpg-help">The saved token or SSH key must have access to both repositories. Copies Git history; LFS content stays in the source LFS storage.</p></div><p class="hpg-help">Creates a new remote branch and selects it for upload. WordPress files stay unchanged.</p><button class="hpg-btn secondary" name="task" value="create_branch" onclick="return confirm('Create branch '+this.form.elements.new_branch.value+' using '+this.form.elements.branch_mode.options[this.form.elements.branch_mode.selectedIndex].text+'?');">Create branch</button></details><details class="hpg-branch-delete"><summary>Delete a branch · admin only</summary><label>Branch to delete</label><select name="delete_branch"><option value="">Choose branch</option><?php $default=get_post_meta($id,'_hpg_default_branch',true)?:'main';foreach($branches as $branch): $protected=in_array($branch,[$default,$c['branch'],$target],true); ?><option value="<?php echo esc_attr($branch); ?>" <?php echo $protected?'disabled':''; ?>><?php echo esc_html($branch.($protected?' · default / active target':'')); ?></option><?php endforeach; ?></select><label>Type the branch name to confirm</label><input name="delete_confirm" autocomplete="off"><p class="hpg-help">Deletes the remote branch. Default and active upload branches cannot be deleted.</p><button class="hpg-btn hpg-delete-profile" name="task" value="delete_branch" onclick="return confirm('Permanently delete GitHub branch '+this.form.elements.delete_branch.value+'?');">Delete GitHub branch</button></details><section class="hpg-card"><?php self::files($id,$c); ?><div class="hpg-row"><button class="hpg-btn secondary" name="task" value="save_files">Save file selection</button></div></section><label>Upload only these staged files/folders · optional, one path or glob per line</label><textarea name="upload_only" rows="3" placeholder="Leave blank for all selected changes"><?php echo esc_textarea(get_post_meta($id,'_hpg_upload_only',true)); ?></textarea><?php endif; ?><div class="hpg-row"><button class="hpg-btn secondary" name="task" value="branches">Refresh branches</button><button class="hpg-btn secondary" name="task" value="preview">Preview upload</button><button class="hpg-btn" name="task" value="push" onclick="return confirm('Push this saved profile to its configured branch? Review file additions and deletions first.');">Push code</button></div></section></main><?php if(HPG_Access::admin()) { self::upload_sidebar($id,$c); } ?></div></form></div><?php
    }
    public static function git() {
        if(!HPG_Access::allowed('push') && !HPG_Access::allowed('merge')) { return; }list($profiles,$id)=self::context();self::head('Git Review & Merge','hpg-git',$profiles,$id);if(!$id) { echo '<p>Create a profile in Settings first.</p></div>';return; }self::result($id);HPG_GitHub::panel($id);$c=HPG_Sync::config($id);$branches=(array)get_post_meta($id,'_hpg_branches',true);$head=!empty($c['date_branch'])?wp_date('Y-m-d'):$c['branch'];$branches=array_unique(array_merge($branches,[$c['branch'],$head]));if(!HPG_Access::admin()) { $branches=array_values(array_diff($branches,['main'])); }sort($branches);$head='';$base='';$last=get_post_meta($id,'_hpg_last_pr',true);if(!is_array($last) || ($last['repo']??'')!==$c['url'] || (!HPG_Access::admin() && in_array('main',[$last['head'],$last['base']],true))) { $last=[]; }
        ?><section class="hpg-card"><h2>Choose branches to merge</h2><?php self::form($id,'hpg-git'); if(HPG_Access::admin()): ?><section class="hpg-scope-box"><h3>GitHub API token · <?php echo esc_html(get_the_title($id)); ?></h3><p class="hpg-help">Repository: <?php echo esc_html($c['url']); ?>. Status: <strong><?php echo get_post_meta($id,'_hpg_token',true)?'Token stored · ********':'No token stored'; ?></strong>. SSH profiles need a token too. The field becomes blank after saving.</p><label>Personal access token</label><input name="token" type="password" autocomplete="new-password" placeholder="<?php echo get_post_meta($id,'_hpg_token',true)?'********':'Paste your GitHub token'; ?>"><?php self::token_eye($id); ?><div class="hpg-row"><button class="hpg-btn secondary" name="task" value="save_token">Save token</button><button class="hpg-btn secondary" name="task" value="test_api">Test API access</button></div></section><?php endif; ?><?php foreach(['compare_head'=>'From branch · changes','compare_base'=>'To branch · destination'] as $name=>$label): ?><label><?php echo esc_html($label); ?></label><select name="<?php echo esc_attr($name); ?>"><option value="" selected>Select branch</option><?php foreach($branches as $branch): ?><option value="<?php echo esc_attr($branch); ?>" <?php selected($name==='compare_head'?$head:$base,$branch); ?>><?php echo esc_html($branch); ?></option><?php endforeach; ?></select><?php endforeach; ?><div class="hpg-merge-direction" role="status">From <strong id="hpg-merge-from"><?php echo esc_html($head); ?></strong> → To <strong id="hpg-merge-to"><?php echo esc_html($base); ?></strong><p>Changes in From will be proposed for To. Your local WordPress files stay unchanged.</p></div><div class="hpg-row"><button class="hpg-btn secondary" name="task" value="branches">Refresh branch list</button><button class="hpg-btn secondary" name="task" value="find_pr">Check existing request</button><button class="hpg-btn secondary" name="task" value="compare">Compare code</button></div><label>Merge request title</label><input name="pr_title" placeholder="Merge from branch into branch"><label>Description</label><textarea name="pr_body" rows="2"></textarea><?php if(HPG_Access::allowed('merge')): ?><div class="hpg-row"><button class="hpg-btn" name="task" value="create_pr" onclick="return confirm('Create a merge request from '+this.form.elements.compare_head.value+' into '+this.form.elements.compare_base.value+'?');">Create merge request</button></div><?php endif; ?><label>Pull request number</label><input type="number" name="pr_number" min="1" value="<?php echo esc_attr($last['number']??''); ?>"><div class="hpg-row"><button class="hpg-btn secondary" name="task" value="review_pr">Review request</button><?php if(HPG_Access::admin()): ?><button class="hpg-btn secondary" name="task" value="load_conflicts">Load conflict editor</button><?php endif; ?><?php if(HPG_Access::allowed('merge')): ?><button class="hpg-btn" name="task" value="accept_pr" onclick="return confirm('Accept and merge the reviewed request on GitHub?');">Accept code / merge</button><?php endif; ?></div><?php HPG_GitHub::conflict_editor($id); ?></form></section></div><?php
    }
}
